package org.brightstats.data;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
public final class InterchangeChecks {
    private static int checks;
    private static void check(boolean valid){checks++;if(!valid)throw new AssertionError("Interchange check "+checks);}
    private interface Action{void run()throws Exception;}
    private static void reject(Action action)throws Exception{try{action.run();throw new AssertionError("Invalid interchange input accepted");}catch(java.io.IOException|IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{Path root=Path.of(args[0]);Gson gson=new GsonBuilder().serializeNulls().create();JsonObject result=new JsonObject();for(String name:List.of("mixed.xlsx","mixed.xls")){var sheets=WorkbookData.sheets(root.resolve(name));check(sheets.getFirst().name().equals("Research α"));var read=WorkbookData.read(root.resolve(name),"Research α",0);check(read.raw().rows().size()==3);check(read.raw().rows().getFirst().get(2).equals("Café"));check(read.raw().rows().get(1).get(2).equals("東京"));check(read.raw().rows().get(2).get(2).equals("A\tB\nC"));check(read.raw().rows().getFirst().get(3).equals("0012"));check(read.raw().rows().getFirst().get(4).equals("2024-02-29T14:30"));check(read.raw().rows().getFirst().get(5).equals("true"));if(!read.raw().rows().getFirst().get(6).equals("4.75"))throw new AssertionError(name+" first row "+read.raw().rows().getFirst());checks++;check(DataPreparation.parse(WorkbookData.delimited(read.raw()),'\t').equals(read.raw()));for(boolean xlsx:new boolean[]{false,true}){Path output=root.resolve("roundtrip-"+name+(xlsx?".xlsx":".xls"));Files.deleteIfExists(output);WorkbookData.write(output,"Roundtrip",read.raw(),xlsx);check(WorkbookData.read(output,"Roundtrip",0).raw().equals(read.raw()));reject(()->WorkbookData.write(output,"Roundtrip",read.raw(),xlsx));}result.add(name,gson.toJsonTree(read));}
        for(String name:List.of("plain.sav","bytecode.sav","compressed.zsav","ranges.sav","numeric.sav","big-endian.sav")){var imported=SpssData.read(root.resolve(name),true);var original=SpssData.read(root.resolve(name),false);check(imported.raw().headers().equals(original.raw().headers()));check(imported.original().equals(original.raw()));if(name.equals("ranges.sav")){check(imported.userMissingCells()==4);check(imported.raw().rows().get(1).getFirst().isEmpty());}else if(!name.equals("numeric.sav")&&!name.equals("big-endian.sav")){check(imported.raw().rows().size()==5);check(imported.raw().headers().getFirst().equals("long_score_name"));check(imported.raw().rows().get(1).getFirst().isEmpty());check(imported.original().rows().get(1).getFirst().equals("-99.0"));check(imported.raw().rows().getFirst().get(2).equals("Café"));check(imported.raw().rows().get(1).get(2).equals("東京"));check(imported.raw().rows().get(1).get(3).length()==510);check(imported.variables().get(1).valueLabels().get("2.0").equals("Treatment"));check(imported.userMissingCells()==2);}result.add(name,gson.toJsonTree(imported));}
        reject(()->SpssData.read(root.resolve("truncated.sav"),true));reject(()->WorkbookData.read(root.resolve("uncached.xlsx"),null,0));reject(()->WorkbookData.read(root.resolve("invalid.xlsx"),null,0));reject(()->WorkbookData.read(root.resolve("mixed.xlsx"),"Absent",0));Files.writeString(root.resolve("java-results.json"),gson.toJson(result));System.out.println("{\"checks\":"+checks+"}");}
}
